query:
mutation MigrateDataWithParams($source: DataSourceInput!, $target: DataTargetInput!, $options: MigrationOptions!) {
  migrateData(source: $source, target: $target, options: $options) {
    success
    migrationId
    status
    progress {
      totalRecords
      processedRecords
      successfulRecords
      failedRecords
      percentage
      estimatedTimeRemaining
    }
    mapping {
      fieldMappings {
        sourceField
        targetField
        transformation
        validated
      }
      relationships {
        sourceTable
        targetTable
        preserveReferences
      }
    }
    validation {
      preChecks
      postChecks
      dataIntegrity
      schemaCompatibility
    }
    rollback {
      available
      estimatedTime
      dependencies
    }
  }
}
